import { test, expect } from '@playwright/test';

test.describe('Save Card Details for Future Purchases', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/checkout');
  });

  test('should successfully save card details and display success message', async ({ page }) => {
    // Verify card input fields are visible
    const cardNumberInput = page.getByLabel('Card Number');
    await expect(cardNumberInput).toBeVisible();
    const cardHolderInput = page.getByLabel('Card Holder Name');
    await expect(cardHolderInput).toBeVisible();
    const expiryDateInput = page.getByLabel('Expiry Date');
    await expect(expiryDateInput).toBeVisible();
    const cvvInput = page.getByLabel('CVV');
    await expect(cvvInput).toBeVisible();

    // Fill in card details
    await cardNumberInput.fill('4111111111111111');
    await cardHolderInput.fill('John Doe');
    await expiryDateInput.fill('12/25');
    await cvvInput.fill('123');

    // Click save button
    const saveButton = page.getByRole('button', { name: /save card/i });
    await saveButton.click();

    // Verify success message appears
    const successMessage = page.getByText(/card saved successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify card details are stored
    const storedCardDetails = page.getByText(/card number: 4111111111111111/i);
    await expect(storedCardDetails).toBeVisible();

    // Verify card details are not stored in clear text
    const clearTextCardDetails = page.getByText(/card number: /i);
    await expect(clearTextCardDetails).not.toBeVisible();

    // Verify card details are not visible in address bar
    const addressBar = page.getByRole('textbox', { name: /address/i });
    await expect(addressBar).toHaveValue('');
  });

  test('should display error when saving card details with invalid format', async ({ page }) => {
    // Verify card input fields are visible
    const cardNumberInput = page.getByLabel('Card Number');
    await expect(cardNumberInput).toBeVisible();
    const cardHolderInput = page.getByLabel('Card Holder Name');
    await expect(cardHolderInput).toBeVisible();
    const expiryDateInput = page.getByLabel('Expiry Date');
    await expect(expiryDateInput).toBeVisible();
    const cvvInput = page.getByLabel('CVV');
    await expect(cvvInput).toBeVisible();

    // Fill in card details with invalid format
    await cardNumberInput.fill('1234');
    await cardHolderInput.fill('Jane Doe');
    await expiryDateInput.fill('12/31');
    await cvvInput.fill('1234');

    // Click save button
    const saveButton = page.getByRole('button', { name: /save card/i });
    await saveButton.click();

    // Verify error message appears
    const errorMessage = page.getByText(/invalid card number/i);
    await expect(errorMessage).toBeVisible();

    // Verify card details are not stored
    const storedCardDetails = page.getByText(/card number: /i);
    await expect(storedCardDetails).not.toBeVisible();

    // Verify success message does not appear
    const successMessage = page.getByText(/card saved successfully/i);
    await expect(successMessage).not.toBeVisible();
  });
});
